function reserve(stock, qty) {
  if (!Number.isInteger(qty) || qty <= 0 || qty > stock) {
    throw new Error("Invalid quantity");
  }
  return stock - qty;
}
const card = cents => `card: ${cents}`;
const cash = cents => `cash: ${cents}`;
function checkout(stock, qty, cents, payment) {
  const remaining = reserve(stock, qty);
  return { remaining, method: payment(cents) };
}
console.log(checkout(5, 2, 1000, card));
